package bo.com.ganadero.sanidad.api;import bo.com.ganadero.animales.domain.*;import bo.com.ganadero.sanidad.application.*;import bo.com.ganadero.sanidad.domain.*;import bo.com.ganadero.shared.api.ApiResponse;import bo.com.ganadero.shared.web.CorrelationIdFilter;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1/jornadas-sanitarias") public class JornadaSanitariaController{private final JornadaSanitariaService s;public JornadaSanitariaController(JornadaSanitariaService s){this.s=s;}@PostMapping ApiResponse<JornadaSanitaria>crear(@Valid@RequestBody CrearJornadaRequest b,HttpServletRequest r){return ok(s.crear(b.command()),r);}@GetMapping ApiResponse<List<JornadaSanitaria>>listar(HttpServletRequest r){return ok(s.listar(),r);}@GetMapping("/animales-elegibles")ApiResponse<List<Animal>>elegibles(@RequestParam UUID propiedadId,@RequestParam(required=false)UUID loteId,@RequestParam(required=false)UUID categoriaId,@RequestParam(required=false)SexoAnimal sexo,HttpServletRequest r){return ok(s.elegibles(propiedadId,loteId,categoriaId,sexo),r);}@GetMapping("/{id}/elegibilidad")ApiResponse<ResultadoElegibilidad>elegibilidad(@PathVariable UUID id,@RequestParam UUID planItemId,@RequestParam LocalDate fechaAplicacion,HttpServletRequest r){return ok(s.elegibilidad(id,planItemId,fechaAplicacion),r);}@PutMapping("/{id}/animales")ApiResponse<List<UUID>>seleccionar(@PathVariable UUID id,@Valid@RequestBody SeleccionAnimalesRequest b,HttpServletRequest r){return ok(s.seleccionar(id,b.planItemId(),b.fechaAplicacion(),b.animalIds()),r);}@PostMapping("/{id}/confirmar")ApiResponse<ConfirmacionJornadaResult>confirmar(@PathVariable UUID id,@Valid@RequestBody ConfirmarJornadaRequest b,HttpServletRequest r){return ok(s.confirmar(id,b.command()),r);}private<T>ApiResponse<T>ok(T d,HttpServletRequest r){Object c=r.getAttribute(CorrelationIdFilter.ATTRIBUTE);return ApiResponse.success(d,c==null?"unknown":c.toString());}}
